    return jdbc.query(
            "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
                    + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date"
                    + " FROM invoices i WHERE i.project_id = ? ORDER BY i.id",
            MAPPER, projectId);
}

